function InicioIcone({tipo}){
  const desenhos={
    privacidade:<><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/></>,
    dados:<><rect x="4" y="2" width="16" height="20" rx="2"/><circle cx="12" cy="8" r="2.5"/><path d="M8 15c0-4 8-4 8 0M8 19h8"/></>,
    perfil:<><rect x="3" y="13" width="4" height="8" rx="1"/><rect x="10" y="8" width="4" height="13" rx="1"/><rect x="17" y="3" width="4" height="18" rx="1"/></>,
    audio:<><rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/></>,
    curriculo:<><path d="M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h8"/></>,
    relogio:<><circle cx="12" cy="12" r="9"/><path d="M12 6v6h5"/></>,
    computador:<><rect x="4" y="3" width="16" height="14" rx="1"/><path d="M2 21h20l-2-4H4z"/></>,
    escudo:<><path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z"/><path d="m8 12 3 3 5-6"/></>,
    externo:<><path d="M14 3h7v7M21 3l-11 11M10 4H4v16h16v-6"/></>
  };
  return <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{desenhos[tipo]}</svg>;
}

