function P1({onNext,onBack}){
  const [ok,setOk]=useState(false);
  const [err,setErr]=useState(false);
  return(
    <div style={{maxWidth:700,margin:"0 auto",padding:"28px 16px"}}>
      <div style={{textAlign:"center",marginBottom:20}}>
        <span style={{background:BP,color:B2,fontSize:10.5,fontWeight:700,padding:"4px 12px",borderRadius:16,border:`1px solid ${B100}`,letterSpacing:"0.1em",textTransform:"uppercase"}}>📋 Etapa 1 de 5</span>
        <h1 style={{fontSize:26,fontWeight:800,color:B1,marginTop:10,marginBottom:6}}>Consentimento e Privacidade</h1>
        <p style={{color:G600,fontSize:13}}>Leia os termos antes de prosseguir.</p>
      </div>
      <Card>
        <div style={{background:B1,borderRadius:12,padding:"18px 20px",color:"rgba(255,255,255,.8)",fontSize:12.5,lineHeight:1.85,maxHeight:200,overflowY:"auto",marginBottom:16,border:"1px solid rgba(0,173,239,.2)"}}>
          <p style={{color:B4,fontWeight:700,fontSize:14,marginBottom:10}}>🔒 Política de Privacidade — LGPD</p>
          <p>A <strong style={{color:"rgba(255,255,255,.95)"}}>Bessani Soluções</strong> coletará seus dados com finalidade exclusiva de avaliação de candidatura.</p>
          <p style={{marginTop:8}}><strong style={{color:"rgba(255,255,255,.95)"}}>Dados coletados:</strong> nome, e-mail, telefone, cidade, estado, respostas comportamentais, áudio e currículo.</p>
          <p style={{marginTop:8}}><strong style={{color:"rgba(255,255,255,.95)"}}>Armazenamento:</strong> Ambiente seguro, acessado apenas pelo RH.</p>
          <p style={{marginTop:8}}><strong style={{color:"rgba(255,255,255,.95)"}}>Prazo:</strong> Até 24 meses. Eliminação disponível mediante solicitação.</p>
        </div>
        <div onClick={()=>{setOk(!ok);setErr(false);}} style={{display:"flex",alignItems:"flex-start",gap:10,padding:"12px 14px",background:ok?BP:G50,borderRadius:9,border:`1.5px solid ${ok?B3:G200}`,cursor:"pointer"}}>
          <input type="checkbox" checked={ok} readOnly style={{width:15,height:15,accentColor:B3,marginTop:2}}/>
          <label style={{fontSize:12.5,color:G600,cursor:"pointer"}}><strong>Li e concordo</strong> com os Termos e autorizo o tratamento dos meus dados pela Bessani Soluções, conforme a LGPD.</label>
        </div>
        {err&&<p style={{color:RED,fontSize:11,marginTop:6}}>Aceite os termos para continuar.</p>}
        <div style={{display:"flex",justifyContent:"space-between",marginTop:20}}>
          <Btn sec onClick={onBack}>← Voltar</Btn>
          <Btn onClick={()=>{if(!ok){setErr(true);return;}onNext();}}>Aceitar e Continuar →</Btn>
        </div>
      </Card>
    </div>
  );
}

function P2({onNext,onBack}){
  const [f,setF]=useState({nome:"",email:"",tel:"",cidade:"",uf:""});
  const [e,setE]=useState({});
  const UFS=["AC","AL","AM","AP","BA","CE","DF","ES","GO","MA","MG","MS","MT","PA","PB","PE","PI","PR","RJ","RN","RO","RR","RS","SC","SE","SP","TO"];
  const up=(k,v)=>setF(p=>({...p,[k]:v}));
  function go(){
    const err={};
    if(!f.nome||f.nome.trim().length<3)err.nome="Obrigatório";
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email))err.email="E-mail inválido";
    if(!f.tel||f.tel.trim().length<8)err.tel="Obrigatório";
    if(!f.cidade||f.cidade.trim().length<2)err.cidade="Obrigatório";
    if(!f.uf)err.uf="Selecione";
    setE(err);
    if(!Object.keys(err).length)onNext(f);
  }
  const inp=(label,k,type="text",opts)=>(
    <div style={{display:"flex",flexDirection:"column",gap:4}}>
      <label style={{fontSize:12,fontWeight:600,color:G700}}>{label} <span style={{color:B3}}>*</span></label>
      {opts
        ?<select value={f[k]} onChange={ev=>up(k,ev.target.value)} style={{border:`1.5px solid ${e[k]?RED:G200}`,borderRadius:9,padding:"9px 11px",fontSize:13,color:G800,background:G50,outline:"none"}}><option value="">Selecione...</option>{opts.map(o=><option key={o}>{o}</option>)}</select>
        :<input type={type} value={f[k]} onChange={ev=>up(k,ev.target.value)} style={{border:`1.5px solid ${e[k]?RED:G200}`,borderRadius:9,padding:"9px 11px",fontSize:13,color:G800,background:G50,outline:"none"}}/>
      }
      {e[k]&&<span style={{fontSize:11,color:RED}}>{e[k]}</span>}
    </div>
  );
  return(
    <div style={{maxWidth:700,margin:"0 auto",padding:"28px 16px"}}>
      <div style={{textAlign:"center",marginBottom:20}}>
        <span style={{background:BP,color:B2,fontSize:10.5,fontWeight:700,padding:"4px 12px",borderRadius:16,border:`1px solid ${B100}`,letterSpacing:"0.1em",textTransform:"uppercase"}}>👤 Etapa 2 de 5</span>
        <h1 style={{fontSize:26,fontWeight:800,color:B1,marginTop:10,marginBottom:6}}>Seus Dados</h1>
        <p style={{color:G600,fontSize:13}}>Preencha corretamente — usaremos para contato.</p>
      </div>
      <Card>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14,marginBottom:8}}>
          <div style={{gridColumn:"1/-1"}}>{inp("Nome Completo","nome")}</div>
          {inp("E-mail","email","email")}
          {inp("Telefone/WhatsApp","tel","tel")}
          {inp("Cidade","cidade")}
          {inp("Estado","uf","text",UFS)}
        </div>
        <div style={{display:"flex",justifyContent:"space-between",marginTop:18}}>
          <Btn sec onClick={onBack}>← Voltar</Btn>
          <Btn onClick={go}>Continuar →</Btn>
        </div>
      </Card>
    </div>
  );
}

// ALTERAÇÃO: grid de perfis (Águia/Lobo/Golfinho/Tubarão) REMOVIDO da etapa 3
// Aparece agora apenas na tela de confirmação final (P6)
function P3({onNext,onBack}){
  const [qi,setQi]=useState(0);
  const [ans,setAns]=useState({});
  const [err,setErr]=useState(false);
  const q=QS[qi];
  function nav(d){
    if(d===1&&!ans[q.id]){setErr(true);return;}
    setErr(false);
    if(d===-1&&qi===0){onBack();return;}
    if(d===1&&qi===QS.length-1){onNext(ans);return;}
    setQi(qi+d);
  }
  return(
    <div style={{maxWidth:700,margin:"0 auto",padding:"28px 16px"}}>
      <div style={{textAlign:"center",marginBottom:20}}>
        <span style={{background:BP,color:B2,fontSize:10.5,fontWeight:700,padding:"4px 12px",borderRadius:16,border:`1px solid ${B100}`,letterSpacing:"0.1em",textTransform:"uppercase"}}>🧠 Etapa 3 de 5</span>
        <h1 style={{fontSize:26,fontWeight:800,color:B1,marginTop:10,marginBottom:6}}>Perfil Comportamental</h1>
        <p style={{color:G600,fontSize:13}}>Escolha a palavra que melhor representa você.</p>
      </div>
      <Card>
        <div style={{display:"flex",justifyContent:"space-between",marginBottom:6}}>
          <span style={{fontSize:12,color:G400}}>Questão <strong style={{color:B1}}>{qi+1}</strong> de <strong style={{color:B1}}>{QS.length}</strong></span>
          <span style={{fontSize:12,color:G400}}>Respondidas: {Object.keys(ans).length}</span>
        </div>
        <div style={{height:4,background:G200,borderRadius:2,marginBottom:16,overflow:"hidden"}}>
          <div style={{height:"100%",width:`${((qi+1)/QS.length)*100}%`,background:`linear-gradient(90deg,${B2},${B4})`,transition:"width .4s"}}/>
        </div>
        <p style={{fontSize:14,fontWeight:700,color:B1,marginBottom:12}}>Q{qi+1}: Qual palavra melhor representa você?</p>
        {q.o.map(o=>{
          const sel=ans[q.id]===o.l;
          return(
            <div key={o.l} onClick={()=>{setAns(p=>({...p,[q.id]:o.l}));setErr(false);}} style={{border:`1.5px solid ${sel?B2:G200}`,borderRadius:9,padding:"11px 13px",display:"flex",alignItems:"center",gap:10,cursor:"pointer",background:sel?BP:G50,marginBottom:7,transition:"all .15s"}}>
              <div style={{width:26,height:26,borderRadius:6,background:sel?B2:B1,display:"flex",alignItems:"center",justifyContent:"center",fontWeight:800,fontSize:12,color:sel?"#fff":B4,flexShrink:0}}>{o.l}</div>
              <span style={{fontSize:13,fontWeight:600,color:G700}}>{o.t}</span>
            </div>
          );
        })}
        {err&&<p style={{color:RED,fontSize:11,marginTop:4}}>Selecione uma alternativa.</p>}
        <div style={{display:"flex",justifyContent:"space-between",marginTop:18}}>
          <Btn sec onClick={()=>nav(-1)}>{qi===0?"← Voltar":"← Anterior"}</Btn>
          <Btn onClick={()=>nav(1)}>{qi===QS.length-1?"Finalizar Etapa →":"Próxima →"}</Btn>
        </div>
      </Card>
    </div>
  );
}

function GravadorAudio({onAudioPronto}){
  const [gravando,setGravando]=useState(false);
  const [audioUrl,setAudioUrl]=useState(null);
  const [audioBlob,setAudioBlob]=useState(null);
  const [erroMic,setErroMic]=useState(null);
  const mediaRecRef=useRef(null);
  const chunksRef=useRef([]);

  // Verifica suporte
  const temSupporte=typeof window!=="undefined"&&!!navigator.mediaDevices&&!!window.MediaRecorder;

  async function iniciarGravacao(){
    setErroMic(null);
    if(!temSupporte){setErroMic("Seu navegador não suporta gravação direta. Use a opção de envio de arquivo.");return;}
    try{
      const stream=await navigator.mediaDevices.getUserMedia({audio:true});
      chunksRef.current=[];
      // Tenta formatos compatíveis — prioriza webm (desktop) e mp4 (iOS)
      const mimeType=MediaRecorder.isTypeSupported("audio/webm;codecs=opus")
        ?"audio/webm;codecs=opus"
        :MediaRecorder.isTypeSupported("audio/mp4")?"audio/mp4":"";
      const rec=mimeType?new MediaRecorder(stream,{mimeType}):new MediaRecorder(stream);
      mediaRecRef.current=rec;
      rec.ondataavailable=e=>{if(e.data.size>0)chunksRef.current.push(e.data);};
      rec.onstop=()=>{
        const blob=new Blob(chunksRef.current,{type:rec.mimeType||"audio/ogg"});
        setAudioBlob(blob);
        setAudioUrl(URL.createObjectURL(blob));
        stream.getTracks().forEach(t=>t.stop());
      };
      rec.start();
      setGravando(true);
    }catch(e){
      if(e.name==="NotAllowedError"||e.name==="PermissionDeniedError"){
        setErroMic("Não foi possível acessar o microfone. Você pode enviar um arquivo de áudio manualmente.");
      }else{
        setErroMic("Erro ao iniciar gravação: "+e.message);
      }
    }
  }

  function pararGravacao(){
    if(mediaRecRef.current&&mediaRecRef.current.state!=="inactive"){
      mediaRecRef.current.stop();
      setGravando(false);
    }
  }

  function gravarNovamente(){
    if(audioUrl)URL.revokeObjectURL(audioUrl);
    setAudioUrl(null);setAudioBlob(null);setErroMic(null);
  }

  function enviarGravacao(){
    if(!audioBlob)return;
    const ext=audioBlob.type.includes("mp4")?"m4a":audioBlob.type.includes("webm")?"webm":"ogg";
    const file=new File([audioBlob],"gravacao."+ext,{type:audioBlob.type});
    onAudioPronto(file);
  }

  return(
    <div>
      {erroMic&&(
        <div style={{background:"rgba(220,38,38,.07)",border:"1px solid rgba(220,38,38,.2)",borderRadius:9,padding:"10px 14px",fontSize:12.5,color:RED,marginBottom:12}}>
          {erroMic}
        </div>
      )}

      {/* Estado: sem áudio gravado */}
      {!audioUrl&&!gravando&&(
        <div style={{textAlign:"center",padding:"28px 16px",border:"2px dashed "+G200,borderRadius:12,background:G50,marginBottom:12}}>
          <div style={{fontSize:40,marginBottom:10}}>🎙️</div>
          <p style={{fontSize:13,color:G600,marginBottom:16}}>Clique para iniciar a gravação</p>
          <button onClick={iniciarGravacao} style={{background:"linear-gradient(135deg,"+B2+","+B3+")",color:"#fff",border:"none",borderRadius:10,padding:"12px 28px",fontWeight:800,fontSize:14,cursor:"pointer",boxShadow:"0 4px 14px rgba(0,93,181,.3)"}}>
            🎙️ Iniciar gravação
          </button>
        </div>
      )}

      {/* Estado: gravando */}
      {gravando&&(
        <div style={{textAlign:"center",padding:"28px 16px",border:"2px solid "+RED,borderRadius:12,background:"rgba(220,38,38,.04)",marginBottom:12}}>
          <div style={{fontSize:40,marginBottom:10,animation:"pulse 1s infinite"}}>🔴</div>
          <p style={{fontSize:13,fontWeight:700,color:RED,marginBottom:16}}>Gravando... fale agora!</p>
          <button onClick={pararGravacao} style={{background:RED,color:"#fff",border:"none",borderRadius:10,padding:"12px 28px",fontWeight:800,fontSize:14,cursor:"pointer"}}>
            ⏹️ Parar gravação
          </button>
        </div>
      )}

      {/* Estado: áudio gravado — ouvir e enviar */}
      {audioUrl&&!gravando&&(
        <div style={{border:"2px solid "+GRN,borderRadius:12,padding:"20px",background:"rgba(22,163,74,.04)",marginBottom:12}}>
          <p style={{fontWeight:800,color:GRN,fontSize:13,marginBottom:12}}>✅ Gravação concluída! Ouça antes de enviar:</p>
          <audio controls src={audioUrl} style={{width:"100%",marginBottom:14}}/>
          <div style={{display:"flex",gap:10,justifyContent:"center",flexWrap:"wrap"}}>
            <button onClick={gravarNovamente} style={{background:"#fff",color:G700,border:"1.5px solid "+G200,borderRadius:9,padding:"9px 18px",fontWeight:700,fontSize:13,cursor:"pointer"}}>
              🔁 Gravar novamente
            </button>
            <button onClick={enviarGravacao} style={{background:"linear-gradient(135deg,"+B2+","+B3+")",color:"#fff",border:"none",borderRadius:9,padding:"9px 20px",fontWeight:800,fontSize:13,cursor:"pointer",boxShadow:"0 4px 14px rgba(0,93,181,.3)"}}>
              ✅ Usar esta gravação
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function UploadPage({step,icon,title,sub,accept,hint,onNext,onBack,isAudio,roteiroAudio=DEFAULT_SCRIPT,loading=false}){
  const [file,setFile]=useState(null);
  const [err,setErr]=useState(false);
  const [modoUpload,setModoUpload]=useState(false);

  function selecionarArquivo(arquivo){
    const mensagem=uploadError(arquivo);
    setErr(mensagem);
    setFile(mensagem?null:arquivo);
  }
  function handleAudioPronto(arquivo){selecionarArquivo(arquivo);}

  return(
    <div style={{maxWidth:700,margin:"0 auto",padding:"28px 16px"}}>
      <div style={{textAlign:"center",marginBottom:20}}>
        <span style={{background:BP,color:B2,fontSize:10.5,fontWeight:700,padding:"4px 12px",borderRadius:16,border:"1px solid "+B100,letterSpacing:"0.1em",textTransform:"uppercase"}}>{icon} Etapa {step} de 5</span>
        <h1 style={{fontSize:26,fontWeight:800,color:B1,marginTop:10,marginBottom:6}}>{title}</h1>
        <p style={{color:G600,fontSize:13}}>{sub}</p>
      </div>
      <Card>
        {/* Script de prospecção */}
        {isAudio&&(
          <div style={{marginBottom:20}}>
            <p style={{fontWeight:800,color:B1,marginBottom:10,fontSize:13}}>📜 Instrução para o áudio</p>
            <div style={{background:B1,borderRadius:9,padding:"14px 16px",color:"rgba(255,255,255,.82)",fontSize:13,lineHeight:1.85,borderLeft:"4px solid "+B4}}>
              <span style={{whiteSpace:"pre-wrap",overflowWrap:"anywhere"}}>{roteiroAudio}</span>
            </div>
          </div>
        )}

        {/* Gravador — só na etapa de áudio */}
        {isAudio&&!file&&(
          <GravadorAudio onAudioPronto={handleAudioPronto}/>
        )}

        {/* Arquivo selecionado via gravação */}
        {isAudio&&file&&(
          <div style={{border:"2px solid "+GRN,borderRadius:12,padding:"16px 20px",background:"rgba(22,163,74,.04)",marginBottom:12,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
            <div>
              <div style={{fontWeight:700,color:GRN,fontSize:14}}>✅ {file.name}</div>
              <div style={{fontSize:12,color:G400,marginTop:2}}>Pronto para envio</div>
            </div>
            <button onClick={()=>setFile(null)} style={{background:"none",color:RED,fontSize:12,cursor:"pointer",border:"none",fontWeight:700}}>✕ Refazer</button>
          </div>
        )}

        {/* Separador "ou envie arquivo" — só no áudio */}
        {isAudio&&(
          <div style={{margin:"16px 0",textAlign:"center"}}>
            <button onClick={()=>setModoUpload(p=>!p)} style={{background:"none",color:G400,border:"none",fontSize:12,cursor:"pointer",textDecoration:"underline"}}>
              {modoUpload?"▲ Ocultar opção de arquivo":"📁 Ou envie um arquivo de áudio"}
            </button>
          </div>
        )}

        {/* Upload manual — sempre visível no currículo, colapsável no áudio */}
        {(!isAudio||modoUpload)&&(
          <div>
            <label style={{border:"2px dashed "+(file?GRN:G200),borderRadius:12,padding:"28px 20px",textAlign:"center",cursor:"pointer",display:"block",background:file?"rgba(22,163,74,.04)":G50,transition:"all .2s"}}>
              <input type="file" accept={accept} style={{display:"none"}} onChange={e=>{if(e.target.files[0])selecionarArquivo(e.target.files[0]);e.target.value="";}}/>
              <div style={{fontSize:32,marginBottom:7}}>{file?"✅":icon}</div>
              <div style={{fontWeight:700,color:G800,marginBottom:4,fontSize:14}}>{file?file.name:"Clique para selecionar o arquivo"}</div>
              <div style={{fontSize:12,color:G400}}>{file?"Arquivo selecionado — pronto para envio":hint}</div>
            </label>
            {file&&<button onClick={()=>setFile(null)} style={{background:"none",color:RED,fontSize:12,cursor:"pointer",border:"none",marginTop:6}}>✕ Remover arquivo</button>}
          </div>
        )}

        <p style={{color:G600,fontSize:12,marginTop:10}}>Tamanho máximo: 4 MB por arquivo.</p>
        {err&&<p role="alert" style={{color:RED,fontSize:12,marginTop:8}}>{err}</p>}

        <div style={{display:"flex",justifyContent:"space-between",marginTop:20}}>
          <Btn sec onClick={onBack}>← Voltar</Btn>
          <Btn onClick={()=>{const mensagem=uploadError(file);if(mensagem){setErr(mensagem);return;}onNext(file);}} disabled={loading}>
            {loading?"Enviando...":(step===5?"Finalizar Candidatura ✓":"Continuar →")}
          </Btn>
        </div>
      </Card>
    </div>
  );
}

// Perfis exibidos APENAS AQUI na confirmação final
function P6({data}){
  const sc={A:0,B:0,C:0,D:0};
  if(data.ans)Object.values(data.ans).forEach(l=>{if(sc[l]!==undefined)sc[l]++;});
  const top=Object.entries(sc).sort((a,b)=>b[1]-a[1])[0];
  const pf=top?PF[top[0]]:PF.D;
  const code=data.codigo||("BSN-"+Date.now().toString().slice(-6));
  return(
    <div style={{maxWidth:700,margin:"0 auto",padding:"28px 16px"}}>
      <Card style={{textAlign:"center",padding:"40px 28px"}}>
        <div style={{width:68,height:68,background:"linear-gradient(135deg,#16A34A,#22C55E)",borderRadius:"50%",display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 18px",fontSize:32,color:"#fff"}}>✓</div>
        <h1 style={{fontSize:28,fontWeight:800,color:B1,marginBottom:10}}>Candidatura Enviada!</h1>
        <p style={{fontSize:14,color:G600,maxWidth:400,margin:"0 auto",lineHeight:1.85}}>Recebemos sua candidatura. Nosso time fará a análise e, havendo aderência, entraremos em contato.</p>
        <div style={{display:"inline-block",background:B1,color:B4,fontSize:12,letterSpacing:"0.14em",padding:"6px 16px",borderRadius:16,marginTop:16,fontWeight:700}}>Código: {code}</div>

        {/* Perfis exibidos APENAS AQUI */}
        <div style={{marginTop:22,padding:"16px",background:BP,borderRadius:12,border:`1px solid ${B100}`}}>
          <p style={{fontWeight:800,color:B1,marginBottom:12,fontSize:13}}>Seu perfil comportamental:</p>
          <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:8}}>
            {Object.entries(sc).map(([k,v])=>{
              const isTop=k===top[0];
              return(
                <div key={k} style={{background:isTop?B1:G50,borderRadius:10,padding:"10px 6px",textAlign:"center",border:`2px solid ${isTop?B4:G200}`}}>
                  <div style={{fontSize:22}}>{PF[k].e}</div>
                  <div style={{fontWeight:800,fontSize:18,color:isTop?"#fff":G700,marginTop:2}}>{v}</div>
                  <div style={{fontSize:10,fontWeight:700,color:isTop?B4:G400,textTransform:"uppercase"}}>{PF[k].n}</div>
                  {isTop&&<div style={{fontSize:9,color:B4,marginTop:2,fontWeight:600}}>dominante</div>}
                </div>
              );
            })}
          </div>
        </div>

        <div style={{marginTop:16,padding:18,background:G50,borderRadius:10,textAlign:"left",maxWidth:360,margin:"16px auto 0",border:`1px solid ${G200}`}}>
          <p style={{fontWeight:800,color:B1,marginBottom:9,fontSize:13}}>Resumo:</p>
          <div style={{fontSize:13,color:G600,lineHeight:2}}>
            <strong style={{color:B1}}>{data.cand?.nome||"Candidato"}</strong><br/>
            📧 {data.cand?.email||"—"}<br/>
            📍 {data.cand?.cidade||"—"} – {data.cand?.uf||""}<br/>
            {pf.e} Perfil dominante: <strong>{pf.n}</strong>
          </div>
        </div>
      </Card>
    </div>
  );
}

function AdminLogin({onLogin,onBack}){
  const [u,setU]=useState("admin");
  const [p,setP]=useState("");
  const [entrando,setEntrando]=useState(false);
  async function entrar(){
    if(entrando)return;
    setEntrando(true);setErr(false);
    try{const res=await fetch("/api/admin/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({usuario:u,senha:p})});if(!res.ok)throw new Error();setP("");onLogin();}
    catch{setErr(true);}
    finally{setEntrando(false);}
  }
  const [err,setErr]=useState(false);
  return(
    <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:`linear-gradient(135deg,${B1},${B2})`,padding:16}}>
      <div style={{background:"#fff",borderRadius:16,padding:"32px 28px",maxWidth:360,width:"100%",boxShadow:"0 8px 40px rgba(0,62,138,.18)"}}>
        <div style={{textAlign:"center",marginBottom:22}}>
          <div style={{background:B1,borderRadius:10,padding:"10px 20px",marginBottom:14,display:"inline-block"}}>
            <div style={{fontWeight:900,fontSize:16,color:B4}}>Bessani Soluções</div>
          </div>
          <h2 style={{fontWeight:800,color:B1,fontSize:"1.15rem"}}>Painel Administrativo</h2>
          <p style={{fontSize:10.5,color:G400,letterSpacing:"0.1em",textTransform:"uppercase",fontWeight:600,marginTop:2}}>Acesso restrito</p>
        </div>
        {err&&<div style={{padding:"9px 13px",borderRadius:9,fontSize:12,fontWeight:600,marginBottom:12,background:"rgba(220,38,38,.07)",color:RED,border:"1px solid rgba(220,38,38,.18)"}}>Usuário ou senha incorretos.</div>}
        <div style={{marginBottom:12}}>
          <label style={{fontSize:12,fontWeight:600,color:G700,display:"block",marginBottom:4}}>Usuário</label>
          <input value={u} onChange={e=>setU(e.target.value)} style={{border:`1.5px solid ${G200}`,borderRadius:9,padding:"9px 11px",fontSize:13,width:"100%",outline:"none",background:G50}}/>
        </div>
        <div style={{marginBottom:18}}>
          <label style={{fontSize:12,fontWeight:600,color:G700,display:"block",marginBottom:4}}>Senha</label>
          <input type="password" value={p} onChange={e=>setP(e.target.value)} style={{border:`1.5px solid ${G200}`,borderRadius:9,padding:"9px 11px",fontSize:13,width:"100%",outline:"none",background:G50}}/>
        </div>
        <Btn onClick={entrar}>{entrando?"Entrando…":"Entrar no Painel"}</Btn>
        <p style={{textAlign:"center",marginTop:6}}><button onClick={onBack} style={{background:"none",color:B3,fontSize:12,fontWeight:600,cursor:"pointer",border:"none"}}>← Voltar ao processo seletivo</button></p>
      </div>
    </div>
  );
}

function Modal({c,onClose}){
  const [ascore,setAscore]=useState(c.as);
  const top=Object.entries({A:c.A,B:c.B,C:c.C,D:c.D}).sort((a,b)=>b[1]-a[1])[0];
  return(
    <div style={{position:"fixed",top:0,left:0,right:0,bottom:0,background:"rgba(0,0,0,.5)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1000,padding:16}} onClick={e=>{if(e.target===e.currentTarget)onClose();}}>
      <div style={{background:"#fff",borderRadius:16,padding:"24px",maxWidth:520,width:"100%",maxHeight:"80vh",overflowY:"auto"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:16}}>
          <div>
            <h2 style={{fontWeight:800,color:B1,fontSize:"1.1rem"}}>{c.nm}</h2>
            <div style={{fontSize:11,color:G400,marginTop:2}}>{c.id} · {c.pr} · {c.dt}</div>
          </div>
          <button onClick={onClose} style={{background:"none",border:"none",color:G400,fontSize:18,cursor:"pointer",lineHeight:1}}>✕</button>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:14}}>
          {[[c.em,"📧"],[c.tel,"📞"],[`${c.ci} – ${c.uf}`,"📍"],[c.st,"📌"]].map(([v,ic])=>(
            <div key={ic} style={{background:G50,borderRadius:8,padding:"8px 11px",fontSize:12,color:G700}}>{ic} {v}</div>
          ))}
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginBottom:14}}>
          {[["Comportamental",c.sc,"/100"],["Currículo",c.cs,"/100"],["Total",c.tt,"/100"]].map(([l,v,s])=>(
            <div key={l} style={{background:G50,borderRadius:8,padding:"10px",textAlign:"center",border:`1px solid ${G200}`}}>
              <div style={{fontSize:10,color:G400,textTransform:"uppercase",fontWeight:700,marginBottom:4}}>{l}</div>
              <div style={{fontSize:20,fontWeight:800,color:scColor(v)}}>{v}</div>
              <div style={{fontSize:10,color:G400}}>{s}</div>
            </div>
          ))}
        </div>
        <div style={{background:BP,borderRadius:10,padding:"12px 14px",marginBottom:14,border:`1px solid ${B100}`}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
            <span style={{fontSize:12,fontWeight:700,color:B1}}>🎵 Score de Áudio</span>
            <span style={{fontSize:11,fontWeight:700,color:B2}}>{ascore.toFixed(1)} / 10</span>
          </div>
          <input type="range" min="0" max="10" step="0.1" value={ascore} onChange={e=>setAscore(parseFloat(e.target.value))} style={{width:"100%",accentColor:B2}}/>
          <div style={{fontSize:10,color:G400,marginTop:4}}>Ajuste manual da nota de áudio</div>
        </div>
        <div style={{background:G50,borderRadius:10,padding:"12px 14px",border:`1px solid ${G200}`}}>
          <div style={{fontWeight:700,color:B1,fontSize:12,marginBottom:8}}>Perfil Comportamental</div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {Object.entries({A:c.A,B:c.B,C:c.C,D:c.D}).map(([k,v])=>(
              <div key={k} style={{flex:1,minWidth:80,background:k===top[0]?B1:G200,borderRadius:8,padding:"8px",textAlign:"center"}}>
                <div style={{fontSize:16}}>{PF[k].e}</div>
                <div style={{fontWeight:800,fontSize:16,color:k===top[0]?"#fff":G700}}>{v}</div>
                <div style={{fontSize:10,color:k===top[0]?B4:G400,fontWeight:700}}>{PF[k].n}</div>
              </div>
            ))}
          </div>
        </div>
        <div style={{display:"flex",gap:8,marginTop:16}}>
          <Btn sec onClick={onClose}>Fechar</Btn>
          <Btn>💾 Salvar Alterações</Btn>
        </div>
      </div>
    </div>
  );
}

// ── Perfil comportamental: ranking (1º e 2º) e barras do card ──
function contagemPerfil(c,k){
  const v=c.json_resultado?.contagem?.[k];
  return v!==undefined && v!==null && Number.isFinite(Number(v))
    ? Math.max(0,Number(v))
    : 0;
}
function perfisOrdenados(c){
  const l=["A","B","C","D"].map(k=>[k,contagemPerfil(c,k)]);
  if(l.every(x=>x[1]===0))return [];
  return l.sort((a,b)=>b[1]-a[1]);
}
function gruposPerfil(c){
  const grupos=[];
  for(const [k,pontos] of perfisOrdenados(c)){
    if(pontos<=0)continue;
    const ultimo=grupos[grupos.length-1];
    if(ultimo && ultimo.pontos===pontos)ultimo.perfis.push(k);
    else grupos.push({pontos,perfis:[k]});
  }
  return grupos.slice(0,2);
}
function PerfilRanking({c}){
  const grupos=gruposPerfil(c);
  if(!grupos.length)return <span style={{color:G400}}>-</span>;
  return(
    <div>
      {grupos.map((g,i)=>(
        <div key={i} style={{fontWeight:i===0?800:400,color:i===0?B1:G400,fontSize:i===0?12:11}}>
          {i===1?"2º ":""}{g.perfis.map(k=>`${PF[k].e} ${PF[k].n}`).join(" / ")}
          {g.perfis.length>1?" (empate)":""}
        </div>
      ))}
    </div>
  );
}
function PerfilBarras({c}){
  const ks=["A","B","C","D"];
  const cont=ks.map(k=>contagemPerfil(c,k));
  if(cont.every(v=>v===0))return <div style={{fontSize:12,color:G400,marginTop:8}}>Perfil comportamental: dados indisponíveis</div>;
  return(
    <div style={{marginTop:10,padding:"10px 12px",background:G50,border:"1px solid "+G200,borderRadius:9}}>
      <div style={{fontSize:11,fontWeight:800,color:B1,textTransform:"uppercase",marginBottom:7}}>Perfil comportamental</div>
      {ks.map((k,i)=>(
        <div key={k} style={{display:"grid",gridTemplateColumns:"96px 1fr 26px",alignItems:"center",gap:8,marginBottom:4}}>
          <span style={{fontSize:12,color:G700,fontWeight:600}}>{PF[k].e} {PF[k].n}</span>
          <div style={{height:8,background:G200,borderRadius:4,overflow:"hidden"}}>
            <div style={{height:"100%",width:Math.min(100,(cont[i]/QS.length)*100)+"%",background:B2,borderRadius:4}}/>
          </div>
          <span style={{fontSize:12,fontWeight:800,color:B1,textAlign:"right"}}>{cont[i]}</span>
        </div>
      ))}
      <div style={{fontSize:10,color:G400,marginTop:4}}>Respostas em cada perfil (de {QS.length})</div>
    </div>
  );
}

function AdminPanel({onBack}){
  const [tab,setTab]=useState("dash");
  const [vagas,setVagas]=useState([]);
  const [vagaSelecionada,setVagaSelecionada]=useState("");
  const consultaAtual=useRef(0);
  async function carregarVagas(){
    const res=await fetch('/api/vagas',{cache:'no-store'});const json=await res.json();if(!res.ok)throw new Error(json.error||'Erro ao buscar vagas');setVagas(json.vagas||[]);return json.vagas||[];
  }
  function selecionarVaga(id){if(id===vagaSelecionada){setSearch('');carregar();return;}consultaAtual.current++;setCandidatos([]);setSearch('');setVagaSelecionada(id);}
  const vagaAtual=vagas.find(v=>v.id===vagaSelecionada);

  const [candidatos,setCandidatos]=useState([]);
  const [loading,setLoading]=useState(true);
  const [erro,setErro]=useState("");
  const [search,setSearch]=useState("");
  const [saving,setSaving]=useState(null);
  const [msg,setMsg]=useState("");

  async function carregar(){
    if(!vagaSelecionada)return;
    const numeroConsulta=++consultaAtual.current;
    try{
      setLoading(true);
      setErro("");
      const res=await fetch('/api/candidatos?vaga_id='+encodeURIComponent(vagaSelecionada),{cache:'no-store'});
      const json=await res.json();
      if(!res.ok) throw new Error(json.error||json.detalhe||'Erro ao buscar candidatos');
      if(numeroConsulta===consultaAtual.current)setCandidatos(json.candidatos||[]);
    }catch(e){
      if(numeroConsulta===consultaAtual.current)setErro(e.message||'Erro ao carregar candidatos');
    }finally{
      if(numeroConsulta===consultaAtual.current)setLoading(false);
    }
  }
  useEffect(()=>{let ativo=true;carregarVagas().then(lista=>{if(ativo){const padrao=lista.find(v=>v.id===process.env.NEXT_PUBLIC_VAGA_ID)||lista[0];setVagaSelecionada(padrao?.id||'');setLoading(false);}}).catch(e=>{if(ativo){setErro(e.message);setLoading(false);}});return()=>{ativo=false;consultaAtual.current++;};},[]);
  useEffect(()=>{if(vagaSelecionada)carregar();},[vagaSelecionada]);

  function cid(c){return c.candidato_id||c.id;}
  function num(v){const n=Number(v);return Number.isFinite(n)?n:null;}
  function scoreTotal(c){return num(c.score_final)??num(c.score_total)??0;}
  function scoreComp(c){return num(c.score_comportamental)??0;}
  function scoreCV(c){return num(c.score_curriculo)??"";}
  function scoreAudio(c){return num(c.score_audio)??"";}
  function nome(c){return c.nome||c.nm||"-";}
  function email(c){return c.email||c.em||"-";}
  function dataCadastro(c){
    if(!c.data_cadastro)return "Não informada";
    const data=new Date(c.data_cadastro);
    if(Number.isNaN(data.getTime()))return "Não informada";
    const opcoes={timeZone:"America/Sao_Paulo"};
    const dia=new Intl.DateTimeFormat("pt-BR",{...opcoes,day:"2-digit",month:"2-digit",year:"numeric"}).format(data);
    const hora=new Intl.DateTimeFormat("pt-BR",{...opcoes,hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).format(data);
    return `${dia} às ${hora}`;
  }
  function cidade(c){return c.cidade||c.ci||"";}
  function estado(c){return c.estado||c.uf||"";}
  function status(c){return c.status||c.st||"-";}
  function perfil(c){return c.perfil_dominante||"-";}
  function arquivos(c,tipo){return (c.arquivos||[]).filter(a=>a.tipo===tipo);}

  async function salvarScore(c){
    const id=cid(c);
    const cv=document.getElementById(`cv-${id}`)?.value;
    const audio=document.getElementById(`audio-${id}`)?.value;
    try{
      setSaving(id);setMsg("");setErro("");
      const res=await fetch('/api/candidatos/score',{
        method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({
          candidato_id:id,
          score_curriculo:cv===""?null:Number(cv),
          score_audio:audio===undefined?Number(scoreAudio(c)||0):(audio===""?null:Number(audio)),
          observacao:document.getElementById(`observacao-${id}`)?.value||'',
          score_comportamental:scoreComp(c)
        })
      });
      const json=await res.json();
      if(!res.ok) throw new Error(json.error||json.detalhe||'Erro ao salvar score');
      setMsg('Score salvo com sucesso.');
      await carregar();
    }catch(e){
      setErro(e.message||'Erro ao salvar score');
    }finally{
      setSaving(null);
    }
  }

  async function salvarDecisao(c, decisao){
    try{setErro('');const res=await fetch('/api/candidatos/decisao',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({candidato_id:cid(c),decisao})});const json=await res.json();if(!res.ok)throw new Error(json.error);await carregar();}
    catch(e){setErro(e.message||'Não foi possível salvar a decisão.');}
  }
  async function excluirCandidato(c){
    const id=cid(c);
    const nomeCandidato=nome(c);

    if(!id){
      alert("Não foi possível identificar este candidato.");
      return;
    }

    const confirmar=window.confirm(
      `Tem certeza que deseja excluir definitivamente ${nomeCandidato} e todos os arquivos dele?

Essa ação não pode ser desfeita.`
    );

    if(!confirmar) return;

    try{
      setSaving(id);
      setMsg("");
      setErro("");

      const res=await fetch("/api/candidatos/delete",{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({candidato_id:id})
      });

      const json=await res.json();
      if(!res.ok) throw new Error(json.detalhe||json.error||"Erro ao excluir candidato");

      setMsg("Candidato excluído com sucesso.");
      await carregar();
    }catch(e){
      setErro(e.message||"Erro ao excluir candidato");
      alert("Erro ao excluir: "+(e.message||"Erro desconhecido"));
    }finally{
      setSaving(null);
    }
  }

  const rankingCompleto=[...candidatos].sort((a,b)=>scoreTotal(b)-scoreTotal(a));
  function posicaoNaVaga(c){
    const grupo=rankingCompleto.filter(item=>(item.vaga_id||"")===(c.vaga_id||""));
    const salva=Number(c.posicao_ranking);
    return {posicao:Number.isInteger(salva)&&salva>0?salva:grupo.findIndex(item=>cid(item)===cid(c))+1,total:grupo.length};
  }
  const filtrados=rankingCompleto.filter(c=>!search||nome(c).toLowerCase().includes(search.toLowerCase())||email(c).toLowerCase().includes(search.toLowerCase()));

  const media=filtrados.length?Math.round(filtrados.reduce((s,c)=>s+scoreTotal(c),0)/filtrados.length):0;
  const tabs=[{id:"vagas",l:"Vagas"},{id:"dash",l:"Dashboard"},{id:"rank",l:"Ranking"},{id:"cands",l:"Candidatos"}];

  function ArquivoBotoes({c,tipo,label}){
    const lista=arquivos(c,tipo);
    if(!lista.length)return <span style={{fontSize:11,color:G400}}>Não enviado</span>;
    const a=lista[0];
    const url=a.public_url||a.url||a.url_publica;
    if(!url)return <span style={{fontSize:11,color:G400}}>Arquivo sem link</span>;
    const controles=(
      <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}>
        {tipo==='audio'&&<audio controls src={url} style={{height:32,maxWidth:220}}/>}
        <a href={url} target="_blank" rel="noreferrer" style={{fontSize:11,fontWeight:800,color:B2,textDecoration:"none",border:`1px solid ${B100}`,padding:"5px 8px",borderRadius:7,background:BP}}>{tipo==='audio'?'Abrir áudio':'Visualizar CV'}</a>
        <a href={url} download={a.nome_arquivo||label} style={{fontSize:11,fontWeight:800,color:G700,textDecoration:"none",border:`1px solid ${G200}`,padding:"5px 8px",borderRadius:7,background:"#fff"}}>Baixar</a>
      </div>
    );
    return tipo==='audio'?<ChecklistAudio c={c} controles={controles}/>:controles;
  }

  // ── Checklist de avaliação de áudio ─────────────────────────────
  const CRITERIOS_AUDIO=[
    {key:"diccao",    label:"Dicção",       peso:0.10, opcoes:[{l:"Excelente",v:100},{l:"Boa",v:80},{l:"Regular",v:60},{l:"Ruim",v:20}]},
    {key:"velocidade",label:"Velocidade",   peso:0.08, opcoes:[{l:"Ideal",v:100},{l:"Rápida demais",v:60},{l:"Lenta demais",v:60}]},
    {key:"entonacao", label:"Entonação",    peso:0.10, opcoes:[{l:"Excelente",v:100},{l:"Boa",v:80},{l:"Fraca",v:40}]},
    {key:"seguranca", label:"Segurança",    peso:0.15, opcoes:[{l:"Muito seguro",v:100},{l:"Médio",v:70},{l:"Baixo",v:30}]},
    {key:"naturalidade",label:"Naturalidade",peso:0.10,opcoes:[{l:"Natural",v:100},{l:"Levemente engessado",v:70},{l:"Robótico",v:30}]},
    {key:"clareza",   label:"Clareza",      peso:0.15, opcoes:[{l:"Muito claro",v:100},{l:"Médio",v:70},{l:"Confuso",v:30}]},
    {key:"postura",   label:"Postura",      peso:0.10, opcoes:[{l:"Excelente",v:100},{l:"Adequado",v:80},{l:"Inadequado",v:20}]},
    {key:"energia",   label:"Energia",      peso:0.07, opcoes:[{l:"Presente",v:100},{l:"Neutro",v:70},{l:"Ausente",v:30}]},
    {key:"conducao",  label:"Condução",     peso:0.10, opcoes:[{l:"Conduz bem",v:100},{l:"Médio",v:70},{l:"Passivo/perdido",v:30}]},
    {key:"script",    label:"Script",       peso:0.05, opcoes:[{l:"Seguiu bem",v:100},{l:"Adaptou bem",v:85},{l:"Fugiu do objetivo",v:30}]},
  ];

  function ChecklistAudio({c,controles}){
    const id=cid(c);
    const [aberto,setAberto]=useState(false);
    const [vals,setVals]=useState({});

    function setCheck(key,val){setVals(p=>({...p,[key]:val}));}

    const completo=CRITERIOS_AUDIO.every(cr=>vals[cr.key]!==undefined);
    const score=completo?Math.round(CRITERIOS_AUDIO.reduce((s,cr)=>s+(cr.opcoes.find(op=>op.l===vals[cr.key]).v*cr.peso),0)):null;

    async function salvarChecklist(){
      if(!completo)return;
      try{
        setSaving(id);setMsg("");setErro("");
        const cv=document.getElementById("cv-"+id)?.value;
        const res=await fetch("/api/candidatos/score",{
          method:"POST",headers:{"Content-Type":"application/json"},
          body:JSON.stringify({
            candidato_id:id,
            score_curriculo:cv===""?null:Number(cv),
            score_audio:score,
            criterios_audio:Object.fromEntries(CRITERIOS_AUDIO.map(cr=>[cr.key,cr.opcoes.find(op=>op.l===vals[cr.key]).v])),
            observacao:document.getElementById(`observacao-${id}`)?.value||'',
          score_comportamental:scoreComp(c)
          })
        });
        const json=await res.json();
        if(!res.ok)throw new Error(json.error||json.detalhe||"Erro ao salvar");
        setMsg("Score salvo com sucesso.");
        setAberto(false);
        await carregar();
      }catch(e){setErro(e.message||"Erro ao salvar");}
      finally{setSaving(null);}
    }

    return(
      <div>
        <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
          {controles}
        <button onClick={()=>setAberto(p=>!p)} style={{background:aberto?B1:B2,color:"#fff",border:"1.5px solid "+(aberto?B1:B2),borderRadius:8,padding:"7px 12px",fontWeight:800,fontSize:12,cursor:"pointer",display:"flex",alignItems:"center",gap:6}}>
          {"🎧 "+(aberto?"Fechar avaliação":"Avaliar áudio")}
          {!aberto&&scoreAudio(c)>0&&<span style={{background:B2,color:"#fff",borderRadius:10,padding:"1px 7px",fontSize:10,marginLeft:4}}>{scoreAudio(c)}</span>}
        </button>
        </div>

        {aberto&&(
          <div style={{marginTop:10,border:"1.5px solid "+B100,borderRadius:10,overflow:"hidden"}}>
            <div style={{background:B1,padding:"8px 14px",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
              <span style={{color:"#fff",fontWeight:800,fontSize:12}}>Checklist de Avaliação — Áudio</span>
              {score!==null
                ?<span style={{background:score>=70?"#16A34A":score>=50?"#D97706":"#DC2626",color:"#fff",fontWeight:800,fontSize:13,padding:"2px 12px",borderRadius:12}}>Score: {score}/100</span>
                :<span style={{color:"rgba(255,255,255,.6)",fontSize:11}}>Preencha todos os critérios</span>
              }
            </div>
            <div style={{background:"#fff",padding:"12px 14px",display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
              {CRITERIOS_AUDIO.map(cr=>(
                <div key={cr.key} style={{background:G50,borderRadius:8,padding:"9px 11px",border:"1px solid "+(vals[cr.key]!==undefined?B100:G200)}}>
                  <div style={{display:"flex",justifyContent:"space-between",marginBottom:6}}>
                    <span style={{fontSize:11,fontWeight:800,color:B1,textTransform:"uppercase"}}>{cr.label}</span>
                    <span style={{fontSize:10,color:G400}}>peso {Math.round(cr.peso*100)}%</span>
                  </div>
                  <div style={{display:"flex",flexWrap:"wrap",gap:4}}>
                    {cr.opcoes.map(op=>{
                      const sel=vals[cr.key]===op.l;
                      return(
                        <button key={op.l} aria-pressed={sel} onClick={()=>setCheck(cr.key,op.l)} style={{fontSize:10.5,fontWeight:sel?800:500,padding:"4px 8px",borderRadius:6,cursor:"pointer",background:sel?B2:"#fff",color:sel?"#fff":G600,border:"1.5px solid "+(sel?B2:G200)}}>
                          {op.l}
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
            <div style={{background:G50,padding:"10px 14px",borderTop:"1px solid "+G200,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
              {!completo
                ?<span style={{fontSize:11,color:AMB}}>{"⚠️ Preencha todos os critérios para calcular o score"}</span>
                :<span style={{fontSize:12,fontWeight:800,color:GRN}}>{"✅ Score calculado: "+score+"/100"}</span>
              }
              <button onClick={salvarChecklist} disabled={!completo||saving===id} style={{background:completo?B2:G200,color:completo?"#fff":G400,border:"none",borderRadius:8,padding:"8px 16px",fontWeight:800,fontSize:12,cursor:completo?"pointer":"not-allowed"}}>
                {saving===id?"Salvando...":"💾 Salvar avaliação"}
              </button>
            </div>
          </div>
        )}
      </div>
    );
  }

  function AvaliacaoCurriculo({c}){
    const id=cid(c);
    return(
      <div style={{display:"flex",gap:8,alignItems:"end",flexWrap:"wrap"}}>
        <ArquivoBotoes c={c} tipo="curriculo" label="curriculo"/>
          <div>
            <label style={{fontSize:10,fontWeight:800,color:G400,textTransform:"uppercase"}}>Nota do currículo</label>
            <input id={"cv-"+id} type="number" min="0" max="100" step="1" defaultValue={scoreCV(c)} placeholder="0-100" style={{width:100,border:"1px solid "+G200,borderRadius:7,padding:"7px 8px",fontWeight:800}}/>
          </div>
          <button onClick={()=>salvarScore(c)} disabled={saving===id} style={{background:B2,color:"#fff",border:"none",borderRadius:8,padding:"9px 10px",fontWeight:800,cursor:"pointer",alignSelf:"end"}}>
            {saving===id?"Salvando...":"Avaliar currículo"}
          </button>
      </div>
    );
  }

  function ScoreInputs({c}){
    const id=cid(c);
    return(
      <div style={{display:"flex",flexDirection:"column",gap:10}}>
        <div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(95px,1fr))",gap:8,alignItems:"end"}}>
          <div>
            <label style={{fontSize:10,fontWeight:800,color:G400,textTransform:"uppercase"}}>Comp.</label>
            <input value={scoreComp(c)} readOnly style={{width:"100%",border:"1px solid "+G200,borderRadius:7,padding:"7px 8px",background:G50,fontWeight:800,color:B1}}/>
          </div>

          <div>
            <label style={{fontSize:10,fontWeight:800,color:G400,textTransform:"uppercase"}}>Áudio</label>
            <input value={scoreAudio(c)||""} readOnly style={{width:"100%",border:"1px solid "+G200,borderRadius:7,padding:"7px 8px",background:G50,fontWeight:800,color:B1}}/>
          </div>

        </div>
      </div>
    );
  }

  return(
    <div style={{minHeight:"calc(100vh - 56px)",background:G100}}>
      <div style={{background:`linear-gradient(135deg,${B1},#002B6B)`,display:"flex",borderBottom:"1px solid rgba(255,255,255,.08)",overflowX:"auto"}}>
        {tabs.map(t=>(
          <button key={t.id} onClick={()=>setTab(t.id)} style={{padding:"13px 15px",background:"none",border:"none",color:tab===t.id?B4:"rgba(255,255,255,.5)",fontWeight:tab===t.id?700:500,fontSize:12.5,cursor:"pointer",borderBottom:tab===t.id?`2px solid ${B4}`:"2px solid transparent",whiteSpace:"nowrap"}}>{t.l}</button>
        ))}
        <div style={{flex:1}}/>
        <button onClick={onBack} style={{padding:"13px 15px",background:"none",border:"none",color:"rgba(255,255,255,.6)",fontSize:12,cursor:"pointer",whiteSpace:"nowrap"}}>← Público</button>
      </div>

      <div style={{maxWidth:1200,margin:"0 auto",padding:"22px 18px"}}>
        {erro&&<div style={{background:"rgba(220,38,38,.08)",color:RED,border:"1px solid rgba(220,38,38,.2)",borderRadius:9,padding:"10px 14px",fontSize:13,marginBottom:12}}>Erro: {erro}</div>}
        {msg&&<div style={{background:"rgba(22,163,74,.08)",color:GRN,border:"1px solid rgba(22,163,74,.2)",borderRadius:9,padding:"10px 14px",fontSize:13,marginBottom:12}}>{msg}</div>}

        <Card style={{marginBottom:18}}><label style={{fontWeight:700,color:B1}}>Vaga selecionada <select aria-label="Vaga selecionada" value={vagaSelecionada} onChange={e=>selecionarVaga(e.target.value)} style={{marginLeft:10,padding:9,border:'1px solid '+G200,borderRadius:8,maxWidth:'100%'}}><option value="">Selecione uma vaga</option>{vagas.map(v=><option key={v.id} value={v.id}>{v.titulo}{v.status==='ativa'?'':' ('+(v.status==='inativa'?'pausada':'encerrada')+')'}</option>)}</select></label><p style={{fontSize:12,color:G600,marginBottom:0}}>Indicadores, candidatos e posições correspondem à vaga selecionada.</p></Card>
        {tab==="vagas"&&<GestaoVagas vagas={vagas} onRefresh={carregarVagas} onSelect={selecionarVaga}/>}
        {tab==="dash"&&(<>
          <h2 style={{fontWeight:800,color:B1,marginBottom:18,fontSize:"1.3rem"}}>Visão Geral</h2>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))",gap:12,marginBottom:20}}>
            {[["Candidatos",String(filtrados.length),"Total recebido"],["Score Médio",String(media),"/100"],["Com currículo",String(filtrados.filter(c=>arquivos(c,'curriculo').length).length),"Arquivos"],["Com áudio",String(filtrados.filter(c=>arquivos(c,'audio').length).length),"Arquivos"]].map(([l,v,s])=>(
              <div key={l} style={{background:"#fff",borderRadius:9,padding:"16px 14px",border:`1px solid ${G200}`,position:"relative",overflow:"hidden"}}>
                <div style={{position:"absolute",top:0,left:0,width:4,height:"100%",background:`linear-gradient(180deg,${B2},${B4})`}}/>
                <div style={{fontSize:10,fontWeight:700,letterSpacing:"0.07em",textTransform:"uppercase",color:G400,marginBottom:5}}>{l}</div>
                <div style={{fontSize:"1.8rem",fontWeight:800,color:B1}}>{v}</div>
                <div style={{fontSize:10.5,color:G400,marginTop:1}}>{s}</div>
              </div>
            ))}
          </div>
        </>)}

        {(tab==="rank"||tab==="dash")&&(<Card style={{marginBottom:18}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:12,flexWrap:"wrap",marginBottom:14}}>
            <h2 style={{fontWeight:800,color:B1,fontSize:"1.2rem"}}>🏆 Ranking de Candidatos</h2>
            <button onClick={carregar} style={{background:BP,color:B1,border:`1px solid ${B100}`,borderRadius:8,padding:"8px 12px",fontWeight:800,cursor:"pointer"}}>Atualizar</button>
          </div>
          <div style={{background:BP,borderRadius:9,padding:12,marginBottom:14,color:B1,fontSize:13}}><strong>Composição da nota final</strong><div style={{marginTop:5}}>Comportamental <strong>40%</strong> · Currículo <strong>30%</strong> · Áudio <strong>30%</strong></div><div style={{fontSize:12,color:G600,marginTop:5}}>Itens não enviados recebem nota zero no cálculo.</div><div style={{marginTop:8}}>Maior influência comportamental: {vagaAtual?['A','B','C','D'].filter(k=>Number(vagaAtual['peso_perfil_'+k.toLowerCase()])===2).map(k=>PF[k].e+' '+PF[k].n).join(' · ')||'Todos os perfis com influência normal':'Selecione uma vaga'}</div></div>
          {loading&&<p style={{color:G600}}>Carregando candidatos...</p>}
          {!loading&&!filtrados.length&&<p style={{color:G600}}>Nenhum candidato encontrado ainda.</p>}
          {!loading&&!!filtrados.length&&<div style={{overflowX:"auto"}}>
            <table style={{width:"100%",borderCollapse:"collapse",minWidth:760}}>
              <thead><tr style={{background:G50}}>{["#","Nome","Perfil","Comp.","CV","Áudio","Final","Status"].map(h=><th key={h} style={{padding:"8px 10px",fontSize:10,fontWeight:800,letterSpacing:"0.07em",textTransform:"uppercase",color:G400,textAlign:"left"}}>{h}</th>)}</tr></thead>
              <tbody>{filtrados.map((c,i)=>(
                <tr key={cid(c)||i} style={{borderTop:`1px solid ${G100}`}}>
                  <td style={{padding:"10px"}}>{posicaoNaVaga(c).posicao}</td>
                  <td style={{padding:"10px"}}><strong>{nome(c)}</strong><div style={{fontSize:11,color:G400}}>{email(c)} · {cidade(c)} {estado(c)}</div></td>
                  <td style={{padding:"10px"}}><PerfilRanking c={c}/></td>
                  <td style={{padding:"10px",fontWeight:800,color:B1}}>{scoreComp(c)}</td>
                  <td style={{padding:"10px",fontWeight:800}}>{scoreCV(c)===""?"-":scoreCV(c)}</td>
                  <td style={{padding:"10px",fontWeight:800}}>{scoreAudio(c)===""?"-":scoreAudio(c)}</td>
                  <td style={{padding:"10px",fontWeight:900,color:scColor(scoreTotal(c))}}>{scoreTotal(c)||"-"}</td>
                  <td style={{padding:"10px"}}>{status(c)}</td>
                </tr>
              ))}</tbody>
            </table>
          </div>}
        </Card>)}

        {tab==="cands"&&(<>
          <style>{`.candidato-layout{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:20px}@media(max-width:900px){.candidato-layout{grid-template-columns:minmax(0,1fr)}}`}</style>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,flexWrap:"wrap",gap:10}}>
            <h2 style={{fontWeight:800,color:B1,fontSize:"1.3rem"}}>Candidatos</h2>
            <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap"}}>
              <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar nome ou e-mail..." style={{border:`1.5px solid ${G200}`,borderRadius:8,padding:"7px 12px",fontSize:12.5,outline:"none",width:240,background:G50}}/>
              <button onClick={carregar} disabled={loading||!vagaSelecionada} style={{background:BP,color:B1,border:`1px solid ${B100}`,borderRadius:8,padding:"8px 12px",fontWeight:800,cursor:loading||!vagaSelecionada?"default":"pointer",opacity:(loading||!vagaSelecionada)?0.6:1}}>{loading?"Atualizando...":"Atualizar"}</button>
            </div>
          </div>
          {loading&&<p role="status">Carregando candidatos...</p>}
          {!loading&&!erro&&!filtrados.length&&<Card><p role="status" style={{color:G600}}>{search.trim()?"Nenhum candidato encontrado para esta busca. Limpe a busca ou clique em Atualizar.":"Nenhum candidato nesta vaga. Clique em Atualizar para buscar novas inscrições."}</p></Card>}
          {!loading&&filtrados.map(c=>(
            <Card key={cid(c)} style={{marginBottom:20}}>
              <div style={{display:"flex",gap:12,justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",marginBottom:20}}>
                <div style={{minWidth:0}}>
                  <h3 style={{color:B1,fontWeight:900,fontSize:20,marginBottom:5}}>{nome(c)}</h3>
                  <div style={{fontSize:12,color:G600,overflowWrap:"anywhere"}}>{email(c)} · {cidade(c)} {estado(c)} · Código: {c.codigo||'-'}</div>
                  <div style={{fontSize:12,color:G600,marginTop:7}}>Cadastrado em: <strong>{dataCadastro(c)}</strong> <span style={{fontSize:11}}>(horário de Brasília)</span></div>
                </div>
                <span style={{padding:"6px 10px",border:"1px solid "+B100,borderRadius:8,background:BP,color:B1,fontSize:12,fontWeight:700}}>{status(c).replace(/_/g," ")}</span>
              </div>
              <div style={{display:'flex',gap:14,flexWrap:'wrap',marginBottom:16,alignItems:'center'}}>
                <label style={{fontSize:13,color:B1}}>Decisão de seleção: <select aria-label="Decisão de seleção" value={c.decisao_selecao||'em_analise'} onChange={e=>salvarDecisao(c,e.target.value)} style={{padding:8,borderRadius:8,border:'1px solid '+G200}}><option value="em_analise">Em análise</option><option value="aprovado">Aprovado</option><option value="reprovado">Reprovado</option></select></label>
                <label style={{fontSize:13,color:B1}}>Observação da avaliação: <textarea id={`observacao-${cid(c)}`} maxLength={3000} defaultValue={c.observacao_avaliacao||''} placeholder="Registre o motivo da nota; será salvo ao avaliar currículo ou áudio." style={{display:'block',minWidth:260,padding:8,borderRadius:8,border:'1px solid '+G200}}/></label>
                <small style={{color:G600}}>Andamento: {status(c).replace(/_/g,' ')}. A decisão não altera as notas.</small>
              </div>
              <div className="candidato-layout">
                <div style={{display:"flex",flexDirection:"column",gap:14,minWidth:0}}>
                  <section style={{border:"1px solid "+G200,borderRadius:12,padding:16}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,flexWrap:"wrap"}}>
                      <h4 style={{margin:0,color:B1,fontSize:16}}>Perfil comportamental</h4>
                      <span style={{background:B2,color:"#fff",padding:"6px 10px",borderRadius:8,fontSize:12,fontWeight:800}}>Nota {scoreComp(c)} / 100</span>
                    </div>
                    <PerfilBarras c={c}/>
                  </section>
                  <section style={{border:"1px solid "+G200,borderRadius:12,padding:16}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,marginBottom:12}}>
                      <h4 style={{margin:0,color:B1,fontSize:16}}>Currículo</h4>
                      <span style={{background:B2,color:"#fff",padding:"6px 10px",borderRadius:8,fontSize:12,fontWeight:800}}>Nota {scoreCV(c)===""?"—":scoreCV(c)} / 100</span>
                    </div>
                    <AvaliacaoCurriculo c={c}/>
                  </section>
                  <section style={{border:"1px solid "+G200,borderRadius:12,padding:16}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,marginBottom:12}}>
                      <h4 style={{margin:0,color:B1,fontSize:16}}>Áudio</h4>
                      <span style={{background:B2,color:"#fff",padding:"6px 10px",borderRadius:8,fontSize:12,fontWeight:800}}>Nota {scoreAudio(c)===""?"—":scoreAudio(c)} / 100</span>
                    </div>
                    <ArquivoBotoes c={c} tipo="audio" label="audio"/>{c.audio?.roteiro_audio&&<details style={{marginTop:10,fontSize:12,color:G600}}><summary>Instrução recebida nesta inscrição</summary><p style={{whiteSpace:"pre-wrap"}}>{c.audio.roteiro_audio}</p></details>}
                  </section>
                </div>
                <aside style={{background:BP,border:"1px solid "+B100,borderRadius:12,padding:20,display:"flex",flexDirection:"column",minWidth:0}}>
                  <h4 style={{margin:"0 0 14px",fontSize:18,color:B1}}>🏆 Resultado geral</h4>
                  <div style={{padding:"10px 12px",background:"#fff",borderRadius:8,color:B1,fontSize:14,fontWeight:800}}>{posicaoNaVaga(c).posicao}º lugar de {posicaoNaVaga(c).total} candidatos</div>
                  <div style={{fontSize:64,lineHeight:1.2,fontWeight:900,color:scColor(scoreTotal(c)),margin:"18px 0"}}>{scoreTotal(c)}<span style={{fontSize:20,color:G600,fontWeight:500}}> / 100</span></div>
                  {[["Comportamental",scoreComp(c)],["Currículo",scoreCV(c)],["Áudio",scoreAudio(c)]].map(([label,valor])=>(
                    <div key={label} style={{display:"flex",justifyContent:"space-between",gap:10,padding:"12px 0",borderTop:"1px solid "+B100,color:B1,fontSize:14}}><span>{label}</span><strong>{valor===""?"—":valor}</strong></div>
                  ))}
                  <p style={{fontSize:11,color:G600,lineHeight:1.6}}>Notas atuais da avaliação. Posição na vaga, independentemente da busca.</p>
                  <div style={{marginTop:"auto",paddingTop:24}}>
                    <button onClick={()=>excluirCandidato(c)} disabled={saving===cid(c)} style={{width:"100%",border:"1px solid "+RED,background:"#fff",color:RED,borderRadius:8,padding:"10px 12px",fontWeight:800,cursor:saving===cid(c)?"not-allowed":"pointer",opacity:saving===cid(c)?0.65:1}}>{saving===cid(c)?"Processando...":"Excluir candidato"}</button>
                  </div>
                </aside>
              </div>
            </Card>
          ))}
        </>)}
      </div>
    </div>
  );
}

const VAGA_ID = process.env.NEXT_PUBLIC_VAGA_ID || ''
const EMPRESA_ID = process.env.NEXT_PUBLIC_EMPRESA_ID || ''
const QUESTIONARIO_ID = process.env.NEXT_PUBLIC_QUESTIONARIO_ID || ''

async function apiPost(url, data) {
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  })
  const json = await res.json()
  if (!res.ok) throw new Error(json.error || 'Erro na requisição')
  return json
}

async function apiUpload(url, candidato_id, arquivo) {
  const mensagem = uploadError(arquivo)
  if (mensagem) throw new Error(mensagem)
  const fd = new FormData()
  fd.append('candidato_id', candidato_id)
  fd.append('arquivo', arquivo)
  const res = await fetch(url, { method: 'POST', body: fd })
  return readUploadResponse(res)
}

export default function App(){
  const [vagaPublica,setVagaPublica]=useState(null);
  const [erroVaga,setErroVaga]=useState('');
  const [carregandoVaga,setCarregandoVaga]=useState(true);
  useEffect(()=>{let ativo=true;const params=new URLSearchParams(window.location.search);const query=params.has('vaga')?'?vaga='+encodeURIComponent(params.get('vaga')):'';
    fetch('/api/vagas/publica'+query,{cache:'no-store'}).then(async res=>{const json=await res.json();if(!res.ok)throw new Error(json.error||'Vaga indisponível.');if(ativo)setVagaPublica(json.vaga);}).catch(e=>{if(ativo)setErroVaga(e.message);}).finally(()=>{if(ativo)setCarregandoVaga(false);});return()=>{ativo=false;};},[]);

  const [view,setView]=useState("cand");
  const [step,setStep]=useState(0);
  const [data,setData]=useState({});
  const [loading,setLoading]=useState(false);
  const [erro,setErro]=useState(null);
  const save=(d)=>setData(p=>({...p,...d}));

  async function sairAdmin(){
    try{const res=await fetch('/api/admin/logout',{method:'POST'});if(!res.ok)throw new Error();setView('cand');}
    catch{window.alert('Não foi possível encerrar a sessão. Tente novamente.');}
  }
  if(view==="login") return <AdminLogin onLogin={()=>setView("admin")} onBack={()=>setView("cand")}/>;
  if(view==="admin") return(
    <div style={{fontFamily:"system-ui,sans-serif"}}>
      <Hdr onAdmin={sairAdmin} isAdmin/>
      <AdminPanel onBack={sairAdmin}/>
    </div>
  );

  async function handleDados(formData){
    setLoading(true);setErro(null);
    try{
      const res=await apiPost('/api/candidatos',{
        ...formData,vaga_id:vagaPublica?.id,lgpd_aceito:true,
      });
      save({cand:formData,candidato_id:res.candidato.id,codigo:res.candidato.codigo,roteiro_audio:res.candidato.roteiro_audio_inscricao||DEFAULT_SCRIPT});
      setStep(3);
    }catch(e){setErro(e.message);}
    finally{setLoading(false);}
  }

  async function handleComportamental(ans){
    setLoading(true);setErro(null);
    try{
      await apiPost('/api/comportamental',{
        candidato_id:data.candidato_id,
        respostas:ans,
      });
      save({ans});setStep(4);
    }catch(e){
      setErro(e.message||"Não foi possível salvar as respostas. Tente novamente.");
    }finally{setLoading(false);}
  }

  async function handleUploadAudio(arquivo){
    setLoading(true);setErro(null);
    try{
      await apiUpload('/api/upload/audio',data.candidato_id,arquivo);
      save({audio:arquivo});setStep(5);
    }catch(e){setErro(e.message);}
    finally{setLoading(false);}
  }

  async function handleUploadCurriculo(arquivo){
    setLoading(true);setErro(null);
    try{
      await apiUpload('/api/upload/curriculo',data.candidato_id,arquivo);
      save({cv:arquivo});setStep(6);
    }catch(e){setErro(e.message);}
    finally{setLoading(false);}
  }

  if(carregandoVaga||erroVaga)return <div style={{fontFamily:'system-ui,sans-serif',padding:32,textAlign:'center',color:B1}}><h1>{carregandoVaga?'Carregando oportunidade…':'Vaga indisponível'}</h1><p>{erroVaga}</p>{!carregandoVaga&&<button onClick={()=>window.location.reload()}>Tentar novamente</button>} <button onClick={()=>setView('login')}>Área Admin</button></div>;
  return(
    <div style={{fontFamily:"system-ui,sans-serif",minHeight:"100vh",background:G100}}>
      <div style={{padding:'12px 20px',background:BP,color:B1,fontWeight:700,textAlign:'center'}}>Vaga: {vagaPublica?.titulo}{step===0&&vagaPublica?.descricao&&<p style={{whiteSpace:'pre-wrap',fontWeight:400,fontSize:14,maxWidth:900,margin:'8px auto'}}>{vagaPublica.descricao}</p>}</div>
      {step!==0&&<Hdr onAdmin={()=>setView("login")}/>}
      {step!==0&&<Prog step={step}/>}
      {erro&&<div style={{maxWidth:700,margin:"0 auto",padding:"8px 16px"}}><div style={{background:"rgba(220,38,38,.08)",color:"#DC2626",border:"1px solid rgba(220,38,38,.2)",borderRadius:9,padding:"10px 14px",fontSize:13}}>{erro}</div></div>}
      {loading&&<div style={{textAlign:"center",padding:"6px",fontSize:12,color:"#94A3B8"}}>Aguarde...</div>}
      {step===0&&<P0 onNext={()=>setStep(1)} onAdmin={()=>setView("login")}/>}
      {step===1&&<P1 onNext={()=>setStep(2)} onBack={()=>setStep(0)}/>}
      {step===2&&<P2 onNext={handleDados} onBack={()=>setStep(1)} loading={loading}/>}
      {step===3&&<P3 onNext={handleComportamental} onBack={()=>setStep(2)}/>}
      {step===4&&<UploadPage step={4} icon="🎵" title="Envio de Áudio" sub="Grave o script e envie o arquivo." accept=".mp3,.m4a,.ogg,.opus,.wav,.aac" hint="MP3, M4A, OGG, OPUS, WAV — Máx 4 MB" isAudio roteiroAudio={data.roteiro_audio||vagaPublica?.roteiro_audio||DEFAULT_SCRIPT} onNext={handleUploadAudio} onBack={()=>setStep(3)} loading={loading}/>}
      {step===5&&<UploadPage step={5} icon="📄" title="Envio de Currículo" sub="Envie seu currículo atualizado." accept=".pdf,.docx" hint="PDF ou DOCX — Máx 4 MB" onNext={handleUploadCurriculo} onBack={()=>setStep(4)} loading={loading}/>}
      {step===6&&<P6 data={data}/>}
    </div>
  );
}
